function Questions({ questions, index, dispatch, currAnswer }) {
  const progressValue = ((index + 1) / questions.length) * 100;
  return (
    <div className="questions">
      <progress value={progressValue} max="100" />
      <h2>{questions[index].question}</h2>
      <div className="answers">
        {questions[index].options.map((answer, i) => (
          <button
            key={i}
            className={`option ${currAnswer === i + 1 ? "selected" : ""}`}
            onClick={() => dispatch({ type: "SELECT_ANSWER", payload: i })}
            disabled={currAnswer !== 0}
          >
            {answer}
          </button>
        ))}
      </div>
    </div>
  );
}

export default Questions;
